use serde_json::{json,Value};
use std::{collections::BTreeMap,fs,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
#[derive(Clone,Debug)]struct Queue{retained:bool,current:usize,retired:usize,generations:usize,payload:usize,max_arrays:usize,max_descriptors:usize,live:bool,events:usize}
fn main(){let root=Path::new("/tmp/zopro-retained-deque-buffers");assert_eq!(read(root.join("trace/result.json"))["status"],"complete");let template=read(root.join("trace-template.json"));let mut cases=Vec::new();for mode in ["off","on"]{for case in template["cases"].as_array().unwrap(){let shape=case["shape"].as_str().unwrap();let name=format!("{mode}-w32-{shape}-prove");let text=fs::read_to_string(root.join("trace").join(name).join("stderr.log")).unwrap();let mut queues=BTreeMap::<usize,Queue>::new();for line in text.lines().filter(|l|l.starts_with("ZOPRO_DEQUE_BUFFER ")){let fields=line.split_whitespace().skip(1).map(|s|s.split_once('=').unwrap()).collect::<BTreeMap<_,_>>();let n=|k:&str|fields[k].parse::<usize>().unwrap();let id=n("queue");let current=n("current");let retired=n("retired");let generations=n("generations");let payload=n("payload_size");let is_retained=n("retained")==1;assert_eq!(is_retained,mode=="on");assert!(current.is_power_of_two()&&current>=64);let arrays=(current+retired)*payload;let descriptor_bytes=(generations+1)*n("descriptor_size")+n("vector_capacity")*n("handle_size");let event=fields["event"];
if event=="new"{assert_eq!(current,64);assert_eq!(retired,0);assert_eq!(generations,0);assert!(queues.insert(id,Queue{retained:is_retained,current,retired,generations,payload,max_arrays:arrays,max_descriptors:descriptor_bytes,live:true,events:1}).is_none());}else{let old=queues.get_mut(&id).unwrap();assert!(old.live);assert_eq!(old.payload,payload);assert_eq!(old.retained,is_retained);if event=="resize"{if is_retained{assert!(current>=2*old.current);assert_eq!(retired,old.retired+old.current);assert_eq!(generations,old.generations+1);}old.current=current;old.retired=retired;old.generations=generations;}else{assert_eq!(event,"drop");assert_eq!(old.current,current);assert_eq!(old.retired,retired);assert_eq!(old.generations,generations);old.live=false;}old.events+=1;old.max_arrays=old.max_arrays.max(arrays);old.max_descriptors=old.max_descriptors.max(descriptor_bytes);}
if is_retained{assert!(retired<current);assert!(current+retired<2*current);}else{assert_eq!(retired,0);assert_eq!(generations,0);}
}assert!(queues.len()>=32);let max_cap=queues.values().map(|q|q.current).max().unwrap();let arrays=queues.values().map(|q|q.max_arrays).sum::<usize>();let metadata=queues.values().map(|q|q.max_descriptors).sum::<usize>();let rows=queues.iter().map(|(id,q)|json!({"queue":id,"payload_size":q.payload,"last_current_capacity":q.current,"retired_capacity":q.retired,"generations":q.generations,"max_observed_array_bytes":q.max_arrays,"max_observed_descriptor_and_vector_bytes":q.max_descriptors,"live_at_last_event":q.live,"events":q.events})).collect::<Vec<_>>();cases.push(json!({"shape":shape,"mode":mode,"queues":queues.len(),"max_last_capacity":max_cap,"summed_per_queue_max_array_bytes":arrays,"summed_per_queue_max_descriptor_and_vector_bytes":metadata,"retired_capacity_sum":queues.values().map(|q|q.retired).sum::<usize>(),"growth_events":queues.values().map(|q|q.events-1-usize::from(!q.live)).sum::<usize>(),"details":rows}));}}
let output=json!({"status":"passed","cases":cases,"sdk_requests":72,"exports":18,"array_bound_observed_every_retained_event":true,"qualification":"Separate instrumented32worker all-nine complete SDK runs, four calls including three primes. Capacity events perturb scheduling and cannot establish an uninstrumented maximum. Summed per-queue maxima are an observed storage envelope, not simultaneous allocator peak. OFF accounting omits epoch-retired arrays, so it is not a retained-vs-normal physical-memory comparison. Counts exclude pointed-to job payloads, allocator/Arc/Inner/thread storage and all prover allocations. No speed claim or pressure/universal-memory qualification."});fs::write(root.join("trace-result.json"),format!("{}\n",serde_json::to_string_pretty(&output).unwrap())).unwrap();println!("CAPACITY_TRACE_AUDIT_PASS all18SDK processes, retained geometric bounds checked at every event");}
